test("redirects: followed on the same origin; the key never goes to another origin or from https to http", async (t) => {
  const { mock, client, sleeps } = await setup(t);
  const other = await MockServer.start();
  t.after(() => other.close());

  mock.reply({ status: 301, headers: { location: "/v1/test/moved" } }, { body: { data: { ok: true }, meta } });
  await client._get("/v1/test/item", {});
  assert.deepEqual(mock.requests.map((r) => r.path), ["/v1/test/item", "/v1/test/moved"]);
  assert.equal(mock.requests[1]!.headers[HEADERS.apiKey], "st_live_runtime");

  mock.requests.length = 0;
  mock.reply({ status: 302, headers: { location: `${other.url}/steal` } });
  await assert.rejects(client._get("/v1/test/item", {}), (e: Error) => e instanceof SocialTapError && e.message.includes(other.url));
  assert.equal(other.requests.length, 0);
  assert.equal(mock.requests.length, 1, "a refused redirect isn't retried");
  assert.deepEqual(sleeps, []);

  const hops = async (from: string, location: string) => {
    const seen: string[] = [];
    const c = new Core({
      apiKey: "k",
      baseURL: from,
      fetch: (async (u: URL) => {
        seen.push(u.href);
        return seen.length === 1 ? new Response(null, { status: 307, headers: { location } }) : new Response('{"data":{},"meta":{}}');
      }) as typeof fetch,
    });
    await c._get("/x", {}).catch(() => undefined);
    return seen.length;
  };
  assert.equal(await hops("https://api.example", "http://api.example/x"), 1, "https to http");
  assert.equal(await hops("https://api.example", "https://api.example.evil/x"), 1, "another host");
  assert.equal(await hops("http://api.example", "https://api.example/x"), 2, "http to https, same host");
});

test("api key: option, then environment, else a clear error", async (t) => {
  const { mock, client } = await setup(t);
  mock.reply({ body: { data: { ok: true }, meta } });
  await client._get("/v1/test/item", {});
  assert.equal(mock.requests[0]!.headers[HEADERS.apiKey], "st_live_runtime");
  assert.match(String(mock.requests[0]!.headers["user-agent"]), new RegExp(`socialtap-typescript/${VERSION}`));

  const saved = process.env[API_KEY_ENV];
  t.after(async () => {
    if (saved === undefined) delete process.env[API_KEY_ENV];
    else process.env[API_KEY_ENV] = saved;
  });
  process.env[API_KEY_ENV] = "st_from_env";
  assert.equal(new Core({ baseURL: mock.url }).apiKey, "st_from_env");
  delete process.env[API_KEY_ENV];
  assert.throws(() => new Core(), (e: unknown) => e instanceof SocialTapError && e.message.includes(API_KEY_ENV));
});

