test("iterate follows cursors and stops at the end, max_pages or max_credits", async (t) => {
  const { mock, client } = await setup(t);
  const more = { has_more: true, next_cursor: "c1.a", next_cursor_expires_at: "2030-01-01T00:00:00Z" };
  const page = (p: object, charged = "5"): Reply => ({ body: { data: [1, 2], page: p, meta }, headers: { [HEADERS.creditsCharged]: charged } });
  mock.reply(page(more), page({ has_more: false, next_cursor: null, next_cursor_expires_at: null, end_reason: "platform_limit" }));
  const all = client._iterate<number>("/v1/test/list", { handle: "h" }, 5);
  assert.deepEqual(await all.toArray(), [1, 2, 1, 2]);
  // The API's end reason and the SDK's guards are separate: stopReason "end", endReason the API's page.end_reason.
  assert.deepEqual([all.pagesFetched, all.creditsCharged, all.stopReason, all.endReason], [2, 10, "end", "platform_limit"]);
  assert.equal(mock.requests[1]!.query.get("cursor"), "c1.a");
  assert.equal(mock.requests[1]!.query.get("handle"), "h");

  mock.reply(page(more), page(more), page(more));
  const pages = client._iterate<number>("/v1/test/list", { cursor: "c1.start" }, 5, { maxPages: 2 });
  assert.equal((await pages.toArray()).length, 4);
  assert.equal(pages.stopReason, "max_pages");
  assert.equal(mock.requests[2]!.query.get("cursor"), "c1.start");

  const budget = client._iterate<number>("/v1/test/list", {}, 5, { maxCredits: 9 });
  assert.equal((await budget.toArray()).length, 2);
  assert.deepEqual([budget.pagesFetched, budget.creditsCharged, budget.stopReason], [1, 5, "max_credits"]);
  const none = client._iterate<number>("/v1/test/list", {}, 5, { maxCredits: 4 });
  assert.deepEqual(await none.toArray(), []);
  assert.equal(none.stopReason, "max_credits");
});
